#include <vector>
#include <numeric>

class Solution {
public:
    int numberOfZigZagArrays(int n, int l, int r) {
        const int MOD = 1e9 + 7;
        int m = r - l + 1;
        if (n <= 0 || m <= 0) return 0;
        if (n == 1) return m % MOD;
        std::vector<int> dpInc(m), dpDec(m);
        for (int v = 0; v < m; ++v) {
            dpInc[v] = v;
            dpDec[v] = m - 1 - v;
        }
        for (int step = 3; step <= n; ++step) {
            std::vector<int> prefDec(m + 1, 0);
            for (int i = 0; i < m; ++i) {
                prefDec[i + 1] = (prefDec[i] + dpDec[i]) % MOD;
            }
            std::vector<int> suffInc(m + 1, 0);
            for (int i = m - 1; i >= 0; --i) {
                suffInc[i] = (suffInc[i + 1] + dpInc[i]) % MOD;
            }
            std::vector<int> newInc(m), newDec(m);
            for (int v = 0; v < m; ++v) {
                newInc[v] = prefDec[v];
                newDec[v] = suffInc[v + 1];
            }
            dpInc = std::move(newInc);
            dpDec = std::move(newDec);
        }
        long long total = 0;
        for (int v = 0; v < m; ++v) {
            total = (total + dpInc[v] + dpDec[v]) % MOD;
        }
        return total;
    }
};

